# Generated by QualityPilot — sample smoke test (no login required)
# Title: Smoke: login page loads
import pytest

pytestmark = pytest.mark.asyncio


async def test_smoke_login_page_loads(page, base_url):
    """Opens the app login page and checks core UI is visible."""
    await page.goto(f"{base_url.rstrip('/')}/login", wait_until="domcontentloaded")
    try:
        await page.wait_for_load_state("networkidle", timeout=8000)
    except Exception:
        pass

    # QualityPilot branded login
    brand = page.get_by_text("QualityPilot", exact=False).first
    await brand.wait_for(state="visible", timeout=10000)
    assert await brand.is_visible()

    email = page.locator('input[type="email"]').first
    password = page.locator('input[type="password"]').first
    await email.wait_for(state="visible", timeout=8000)
    await password.wait_for(state="visible", timeout=8000)
    assert await email.is_visible()
    assert await password.is_visible()
